def decode_block_png(relative: str) -> bytes:
    """Decode embedded bytes without reading workspace resources."""
    if relative == 'assets/blindboxchallenge/textures/block/music_box.png':
        return zlib.decompress(base64.b64decode('', validate=True))
    return zlib.decompress(base64.b64decode(BLOCK_PNG_PAYLOADS[relative], validate=True))

def decode_rgba(relative: str) -> bytes:
    """Decode embedded bytes without reading workspace resources."""
    raw = zlib.decompress(base64.b64decode(ITEM_PIXEL_PAYLOADS[relative], validate=True))
    if len(raw) != 16 * 16 * 4:
        raise ValueError(f"Invalid embedded texture payload: {relative}")
    return raw

def decode_item_png(relative: str) -> bytes:
    return zlib.decompress(base64.b64decode(ITEM_PNG_PAYLOADS[relative], validate=True))


